crates/core/src/config.rs::parse_colors.source_code:
fn parse_colors(value: &str, slots: &mut [[u8; 3]]) {
    for (slot, item) in slots.iter_mut().zip(value.split(',')) {
        if let Some(rgb) = color(item.trim()) {
            *slot = rgb;
        }
    }
}

