crates/core/src/config.rs::parse_recent.source_code:
fn parse_recent(value: &str) -> RecentColors {
    let colors: Vec<[u8; 3]> = value
        .split(',')
        .filter_map(|item| color(item.trim()))
        .take(CAPACITY)
        .collect();
    RecentColors::new(&colors)
}

crates/core/src/config.rs::color.source_code:
fn color(text: &str) -> Option<[u8; 3]> {
    let hex = text.strip_prefix('#')?;
    if hex.len() != 6 || !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
        return None;
    }
    let channel = |i: usize| u8::from_str_radix(&hex[i..i + 2], 16).ok();
    Some([channel(0)?, channel(2)?, channel(4)?])
}

crates/core/src/config.rs::parse_widths.source_code:
fn parse_widths(value: &str, slots: &mut [f32]) {
    for (slot, item) in slots.iter_mut().zip(value.split(',')) {
        if let Some(width) = item.trim().parse().ok().and_then(Palette::snap_width) {
            *slot = width;
        }
    }
}

crates/core/src/excalidraw.rs::clipboard.source_code:
pub(crate) fn clipboard<'a>(elements: impl Iterator<Item = &'a Element>) -> Option<String> {
    let mut out = String::from(r#"{"type":"excalidraw/clipboard","elements":["#);
    let mut count = 0_usize;
    for element in elements {
        if count > 0 {
            out.push(',');
        }
        write_element(&mut out, element, count);
        count += 1;
    }
    out.push_str(r#"],"files":{}}"#);
    (count > 0).then_some(out)
}

crates/core/src/excalidraw.rs::write_ele.source_code:
fn write_element(out: &mut String, element: &Element, z: usize) {
    let e = element;
    let [left, top, right, bottom] = e.extent();
    let [red, green, blue] = e.stroke_color();
    // Writing to a String cannot fail.
    let _ = write!(
        out,
        r##"{{"id":"markuli-{id}","type":"freedraw","x":{x},"y":{y},"width":{w},"height":{h},"angle":0,"strokeColor":"#{red:02x}{green:02x}{blue:02x}","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":{sw},"strokeStyle":"solid","roughness":1,"opacity":{op},"groupIds":[],"frameId":null,"index":{index},"roundness":null,"seed":{seed},"version":{version},"versionNonce":{seed},"isDeleted":false,"boundElements":null,"updated":0,"link":null,"locked":false,"points":["##,
        id = e.id(),
        x = Num(e.x()),
        y = Num(e.y()),
        w = Num(right - left),
        h = Num(bottom - top),
        sw = Num(e.stroke_width() * STROKE_WIDTH_PER_PT),
        op = e.opacity(),
        index = Index(z),
        seed = e.seed(),
        version = e.version(),
    );
    for (i, point) in e.points().iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        let _ = write!(out, "[{},{}]", Num(point.x), Num(point.y));
    }
    out.push_str(r#"],"pressures":["#);
    for (i, pressure) in e.pressures().iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        let _ = write!(out, "{}", Num(*pressure));
    }
    let _ = write!(
        out,
        r#"],"simulatePressure":{},"lastCommittedPoint":"#,
        e.simulate_pressure()
    );
    match e.points().last() {
        Some(last) => {
            let _ = write!(out, "[{},{}]", Num(last.x), Num(last.y));
        }
        None => out.push_str("null"),
    }
    out.push('}');
}

