fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    if self.0.is_finite() {
        write!(f, "{}", self.0)
    } else {
        f.write_str("0")
    }
}

crates/core/src/excalidraw.rs::Index.docstring:
/// A fractional index (the `index` field), as JSON: strictly ascending with
/// `z`. Excalidraw's own keys start `a0`..`az` (one digit, base 62) and then
/// `b00`..`bzz`; past that it is `null`, which paste re-numbers.

crates/core/src/excalidraw.rs::Index.fmt.source_code:
fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    const DIGITS: &[u8; 62] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    let digit = |n: usize| char::from(DIGITS[n % 62]);
    match self.0 {
        z if z < 62 => write!(f, "\"a{}\"", digit(z)),
        z if z < 62 + 62 * 62 => {
            let n = z - 62;
            write!(f, "\"b{}{}\"", digit(n / 62), digit(n))
        }
        _ => f.write_str("null"),
    }
}

crates/core/src/freehand.rs::dist2.source_code:
fn dist2(a: V, b: V) -> f64 {
    let d = sub(a, b);
    d[0] * d[0] + d[1] * d[1]
}

crates/core/src/freehand.rs::uni.source_code:
fn uni(a: V) -> V {
    let len = a[0].hypot(a[1]);
    [a[0] / len, a[1] / len]
}

crates/core/src/freehand.rs::lrp.source_code:
fn lrp(a: V, b: V, t: f64) -> V {
    add(a, mul(sub(b, a), t))
}

crates/core/src/freehand.rs::rot_around.source_code:
fn rot_around(a: V, c: V, r: f64) -> V {
    let (s, co) = r.sin_cos();
    let (px, py) = (a[0] - c[0], a[1] - c[1]);
    [px * co - py * s + c[0], px * s + py * co + c[1]]
}

crates/core/src/freehand.rs::stroke_radi.source_code:
fn stroke_radius(size: f64, pressure: f64) -> f64 {
    size * easing(0.5 - THINNING * (0.5 - pressure))
}

crates/core/src/freehand.rs::Scratch.loa.source_code:
pub(crate) fn load(
    &mut self,
    points: impl Iterator<Item = V>,
    mut pressures: impl Iterator<Item = f64>,
) {
    self.input.clear();
    for p in points {
        self.input
            .push([p[0], p[1], pressures.next().unwrap_or(f64::NAN)]);
    }
}

crates/core/src/freehand.rs::Scratch.out.source_code:
pub(crate) fn outline(&mut self, size: f64, last: bool) -> &[V] {
    self.out.clear();
    self.compute_stroke_points(size, last);
    self.compute_outline(size);
    &self.out
}

crates/core/src/freehand.rs::Scratch.com.source_code:
fn compute_stroke_points(&mut self, size: f64, is_complete: bool) {
    // Mirrors `getStrokePoints` step by step (rule 15), for parity diffs.
    self.stroke_points.clear();
    if self.input.is_empty() {
        return;
    }
    let t = 0.15 + (1.0 - STREAMLINE) * 0.85;
    self.pts.clear();
    self.pts.extend_from_slice(&self.input);
    if self.pts.len() == 2 {
        // Extra points avoid "dash" lines. Interpolated points carry no
        // pressure: the library's `lrp` returns 2-vectors.
        // Indexing is safe: the length is exactly 2 here.
        let (first, end) = (self.pts[0], self.pts[1]);
        self.pts.truncate(1);
        for i in 1..5_u8 {
            let p = lrp([first[0], first[1]], [end[0], end[1]], f64::from(i) / 4.0);
            self.pts.push([p[0], p[1], f64::NAN]);
        }
    }
    if self.pts.len() == 1 {
        // Indexing is safe: the length is exactly 1 here.
        let p = self.pts[0];
        self.pts.push([p[0] + 1.0, p[1] + 1.0, p[2]]);
    }
    let pts = &self.pts;
    // `input` is non-empty (checked above), so `pts` has at least one point.
    let Some(&first) = pts.first() else {
        return;
    };
    let mut prev = StrokePoint {
        point: [first[0], first[1]],
        pressure: if first[2] >= 0.0 { first[2] } else { 0.25 },
        vector: [1.0, 1.0],
        distance: 0.0,
        running_length: 0.0,
    };
    self.stroke_points.push(prev);
    let mut reached_minimum = false;
    let mut running_length = 0.0;
    // `pts` is non-empty, so this cannot underflow.
    let max = pts.len().saturating_sub(1);
    for (i, p) in pts.iter().enumerate().skip(1) {
        let target = [p[0], p[1]];
        let point = if is_complete && i == max {
            target
        } else {
            lrp(prev.point, target, t)
        };
        #[allow(clippy::float_cmp, reason = "exact equality is the library's rule")]
        if prev.point == point {
            continue;
        }
        let distance = (point[1] - prev.point[1]).hypot(point[0] - prev.point[0]);
        running_length += distance;
        // Wait for a minimum length at the start of the line to avoid noise.
        if i < max && !reached_minimum {
            if running_length < size {
                continue;
            }
            reached_minimum = true;
        }
        prev = StrokePoint {
            point,
            pressure: if p[2] >= 0.0 { p[2] } else { 0.5 },
            vector: uni(sub(prev.point, point)),
            distance,
            running_length,
        };
        self.stroke_points.push(prev);
    }
    let second_vector = self.stroke_points.get(1).map_or([0.0, 0.0], |s| s.vector);
    if let Some(head) = self.stroke_points.first_mut() {
        head.vector = second_vector;
    }
}

fn compute_outline(&mut self, size: f64) {
    // Long on purpose (rule 15): this mirrors `getStrokeOutlinePoints` line
    // for line, so a change upstream can be diffed and re-ported. Splitting
    // it would hide parity drift.
    let simulate = !self.input.iter().any(|p| p[2] >= 0.0);
    let points = &self.stroke_points;
    let (Some(&first_sp), Some(&last_sp)) = (points.first(), points.last()) else {
        return;
    };
    if size <= 0.0 {
        return;
    }
    let total_length = last_sp.running_length;
    let min_distance = (size * SMOOTHING).powi(2);
    self.left.clear();
    self.right.clear();
    self.start_cap.clear();
    self.end_cap.clear();
    let (left, right) = (&mut self.left, &mut self.right);

    let mut prev_pressure = points.iter().take(10).fold(first_sp.pressure, |acc, curr| {
        let mut pressure = curr.pressure;
        if simulate {
            let sp = (curr.distance / size).min(1.0);
            let rp = (1.0 - sp).min(1.0);
            pressure = (acc + (rp - acc) * (sp * RATE_OF_PRESSURE_CHANGE)).min(1.0);
        }
        f64::midpoint(acc, pressure)
    });
    let mut radius = stroke_radius(size, last_sp.pressure);
    let mut first_radius: Option<f64> = None;
    let mut prev_vector = first_sp.vector;
    let mut pl = first_sp.point;
    let mut pr = pl;
    let (mut tl, mut tr);
    let mut is_prev_point_sharp_corner = false;

    for (i, &sp) in points.iter().enumerate() {
        let StrokePoint {
            point,
            vector,
            distance,
            running_length,
            mut pressure,
        } = sp;
        // Removes noise from the end of the line.
        if i + 1 < points.len() && total_length - running_length < 3.0 {
            continue;
        }
        // THINNING is non-zero for Excalidraw.
        if simulate {
            let sp = (distance / size).min(1.0);
            let rp = (1.0 - sp).min(1.0);
            pressure = (prev_pressure + (rp - prev_pressure) * (sp * RATE_OF_PRESSURE_CHANGE))
                .min(1.0);
        }
        radius = stroke_radius(size, pressure);
        if first_radius.is_none() {
            first_radius = Some(radius);
        }
        radius = radius.max(0.01);

        let next = points.get(i + 1);
        let next_vector = next.map_or(vector, |n| n.vector);
        let next_dpr = if next.is_some() {
            dpr(vector, next_vector)
        } else {
            1.0
        };
        let prev_dpr = dpr(vector, prev_vector);
        let is_point_sharp_corner = prev_dpr < 0.0 && !is_prev_point_sharp_corner;
        let is_next_point_sharp_corner = next_dpr < 0.0;

        if is_point_sharp_corner || is_next_point_sharp_corner {
            // A rounded cap at the corner. 14 iterations: f64 accumulation.
            let offset = mul(per(prev_vector), radius);
            let step = 1.0 / 13.0;
            let mut t = 0.0_f64;
            tl = pl;
            tr = pr;
            while t <= 1.0 {
                tl = rot_around(sub(point, offset), point, FIXED_PI * t);
                left.push(tl);
                tr = rot_around(add(point, offset), point, FIXED_PI * -t);
                right.push(tr);
                t += step;
            }
            pl = tl;
            pr = tr;
            if is_next_point_sharp_corner {
                is_prev_point_sharp_corner = true;
            }
            continue;
        }
        is_prev_point_sharp_corner = false;

        if i + 1 == points.len() {
            let offset = mul(per(vector), radius);
            left.push(sub(point, offset));
            right.push(add(point, offset));
            continue;
        }
        let offset = mul(per(lrp(next_vector, vector, next_dpr)), radius);
        tl = sub(point, offset);
        if i <= 1 || dist2(pl, tl) > min_distance {
            left.push(tl);
            pl = tl;
        }
        tr = add(point, offset);
        if i <= 1 || dist2(pr, tr) > min_distance {
            right.push(tr);
            pr = tr;
        }
        prev_pressure = pressure;
        prev_vector = vector;
    }

    let first_point = first_sp.point;
    let last_point = if points.len() > 1 {
        last_sp.point
    } else {
        add(first_sp.point, [1.0, 1.0])
    };

    if points.len() == 1 {
        // A dot: 13 points around the first point.
        let start = add(
            first_point,
            mul(
                uni(per(sub(first_point, last_point))),
                -first_radius.unwrap_or(radius),
            ),
        );
        let step = 1.0 / 13.0;
        let mut t = step;
        while t <= 1.0 {
            self.out
                .push(rot_around(start, first_point, FIXED_PI * 2.0 * t));
            t += step;
        }
        return;
    }
    if let Some(&r0) = right.first() {
        let step = 1.0 / 13.0;
        let mut t = step;
        while t <= 1.0 {
            self.start_cap
                .push(rot_around(r0, first_point, FIXED_PI * t));
            t += step;
        }
    }
    // A full turn and a half: prevents incorrect caps on sharp end turns.
    let direction = per(mul(last_sp.vector, -1.0));
    let start = add(last_point, mul(direction, radius));
    let step = 1.0 / 29.0;
    let mut t = step;
    while t < 1.0 {
        self.end_cap
            .push(rot_around(start, last_point, FIXED_PI * 3.0 * t));
        t += step;
    }
    self.out.extend_from_slice(left);
    self.out.extend_from_slice(&self.end_cap);
    self.out.extend(right.iter().rev());
    self.out.extend_from_slice(&self.start_cap);
}

crates/core/src/freehand.rs::get_stroke.source_code:
pub fn get_stroke(points: &[[f64; 2]], pressures: &[f64], size: f64, last: bool) -> Vec<[f64; 2]> {
    let mut scratch = Scratch::default();
    scratch.load(points.iter().copied(), pressures.iter().copied());
    scratch.outline(size, last).to_vec()
}

crates/core/src/freehand.rs::get_stroke.docstring:
/// The outline polygon of a Stroke, as Excalidraw computes it: perfect-freehand
/// `getStroke` with the given `size` (the caller converts width to size) and
/// Excalidraw's other options.
///
/// `points` are relative to the Element origin. An empty `pressures` means
/// simulated pressure; otherwise there is one pressure per point. `last` is
/// true once the Stroke is committed.
///
/// This exists for the parity tests against the JS library; the core itself
/// uses the allocation-free [`Scratch`] directly.

crates/core/src/history.rs::Op.source_code:
enum Op {
    /// One committed Stroke. Applied: the Element is the last one in the Ink
    /// and the payload is `None`. Reverted: the payload holds it.
    Add(Option<Element>),
    /// Clear. Applied: the payload holds what was removed and the Ink is
    /// empty. Reverted: the payload is empty and the Ink holds them again.
    Clear(Vec<Element>),
    /// Selected Elements moved. Each entry is an Ink index and the position
    /// the Element is *not* at: applying and reverting swap it in, so undo is
    /// exact (no float drift from adding and subtracting a delta).
    Move(Vec<(usize, f32, f32)>),
    /// Selected Elements deleted. `indices` (ascending) are where they sat in
    /// the Ink; `removed` holds them while the delete is applied and is empty
    /// while it is reverted.
    Delete {
        indices: Vec<usize>,
        removed: Vec<Element>,
    },
    /// One Eraser drag: the Elements it removed and where they were (oldest
    /// first). Applied: they are in the payload. Reverted: the payload is
    /// `None` and they are back in the Ink at their old positions.
    Erase(Vec<(usize, Option<Element>)>),
    /// One style change of the Selection. Each entry is an Ink index and the
    /// style the Element is *not* at: applying and reverting swap it in, like
    /// `Move`.
    Restyle(Vec<(usize, Appearance)>),
}

crates/core/src/history.rs::History.source_code:
pub struct History {
    ops: Vec<Op>,
    /// Entries `..done` are applied; the rest can be redone.
    done: usize,
}

crates/core/src/history.rs::History.reco.source_code:
pub fn record_clear(&mut self, removed: Vec<Element>) {
    self.push(Op::Clear(removed));
}

pub fn record_move(&mut self, before: Vec<(usize, f32, f32)>) {
    self.push(Op::Move(before));
}

pub fn record_delete(&mut self, indices: Vec<usize>, removed: Vec<Element>) {
    self.push(Op::Delete { indices, removed });
}

pub fn record_restyle(&mut self, before: Vec<(usize, Appearance)>) {
    self.push(Op::Restyle(before));
}

pub fn record_erase(&mut self, removed: Vec<(usize, Element)>) {
    if !removed.is_empty() {
        let slots = removed.into_iter().map(|(i, e)| (i, Some(e))).collect();
        self.push(Op::Erase(slots));
    }
}

crates/core/src/history.rs::History.push.source_code:
fn push(&mut self, op: Op) {
    self.ops.truncate(self.done);
    self.ops.push(op);
    self.done += 1;
}

crates/core/src/history.rs::History.rese.source_code:
pub fn reset(&mut self) {
    self.ops.clear();
    self.done = 0;
}

crates/core/src/history.rs::History.can_.source_code:
pub fn can_redo(&self) -> bool {
    self.done < self.ops.len()
}

crates/core/src/history.rs::History.undo.source_code:
pub fn undo(&mut self, ink: &mut Ink, scratch: &mut Scratch) -> bool {
    let Some(index) = self.done.checked_sub(1) else {
        return false;
    };
    let Some(op) = self.ops.get_mut(index) else {
        return false;
    };
    let changed = flip(op, ink, scratch, Direction::Revert);
    self.done = index;
    changed
}

crates/core/src/history.rs::History.redo.source_code:
pub fn redo(&mut self, ink: &mut Ink, scratch: &mut Scratch) -> bool {
    let Some(op) = self.ops.get_mut(self.done) else {
        return false;
    };
    let changed = flip(op, ink, scratch, Direction::Apply);
    self.done += 1;
    changed
}

crates/core/src/history.rs::flip.source_code:
fn flip(op: &mut Op, ink: &mut Ink, scratch: &mut Scratch, direction: Direction) -> bool {
    match (op, direction) {
        (Op::Add(slot), Direction::Revert) => {
            *slot = ink.pop();
            slot.is_some()
        }
        (Op::Add(slot), Direction::Apply) => match slot.take() {
            Some(element) => {
                ink.add(element);
                true
            }
            None => false,
        },
        (Op::Erase(slots), Direction::Revert) => {
            for (index, slot) in slots.iter_mut() {
                if let Some(element) = slot.take() {
                    ink.insert_at(*index, element);
                }
            }
            true
        }
        (Op::Erase(slots), Direction::Apply) => {
            for (index, slot) in slots.iter_mut().rev() {
                *slot = ink.remove_at(*index);
            }
            true
        }
        // Applying and reverting a Clear are the same swap.
        (Op::Clear(payload), _) => {
            ink.swap_elements(payload);
            true
        }
        (Op::Restyle(styles), _) => {
            for (index, style) in styles.iter_mut() {
                if let Some(element) = ink.get_mut(*index) {
                    let current = element.style();
                    element.set_style(*style, scratch);
                    *style = current;
                }
            }
            !styles.is_empty()
        }
        (Op::Move(positions), _) => {
            for (index, x, y) in positions.iter_mut() {
                if let Some(element) = ink.get_mut(*index) {
                    let (ex, ey) = (element.x(), element.y());
                    element.set_position(*x, *y);
                    (*x, *y) = (ex, ey);
                }
            }
            !positions.is_empty()
        }
        (Op::Delete { indices, removed }, Direction::Revert) => {
            for (&index, element) in indices.iter().zip(removed.drain(..)) {
                ink.insert_at(index, element);
            }
            !indices.is_empty()
        }
        (Op::Delete { indices, removed }, Direction::Apply) => {
            for &index in indices.iter().rev() {
                removed.extend(ink.remove_at(index));
            }
            removed.reverse();
            !indices.is_empty()
        }
    }
}

