pub(crate) fn draw(
    target: &mut Painter<'_, '_>,
    icon: &Icon,
    (x, y, size): (f32, f32, f32),
    paint: &Paint<'_>,
) {
    let k = size / icon.view;
    stroke_paths(
        target,
        icon.paths,
        icon.stroke,
        Transform::from_row(k, 0.0, 0.0, k, x, y),
        paint,
    );
}

