fn stroke_paths(
    target: &mut Painter<'_, '_>,
    paths: &[&str],
    width: f32,
    at: Transform,
    paint: &Paint<'_>,
) {
    let stroke = stroke_of(width);
    for d in paths {
        if let Some(path) = svg_path::parse(d) {
            target.stroke_path(&path, paint, &stroke, at);
        }
    }
}

