    /// Marked by the Eraser, removed when its drag ends; drawn faded.
    erasing: bool,
}

crates/core/src/ink.rs::Element.start.source_code:
pub(crate) fn start(id: u64, at: Point, pressure: Option<f32>, style: Appearance) -> Self {
    let simulate_pressure = pressure.is_none_or(|p| (p - 0.5).abs() < f32::EPSILON);
    Self {
        id,
        x: at.x,
        y: at.y,
        points: {
            // Room for a long stroke without regrowing on the hot path.
            let mut points = Vec::with_capacity(256);
            points.push(Point { x: 0.0, y: 0.0 });
            points
        },
        pressures: if simulate_pressure {
            Vec::new()
        } else {
            Vec::from([pressure.unwrap_or(0.5)])
        },
        simulate_pressure,
        stroke_color: style.color,
        stroke_width: style.width,
        opacity: 100,
        #[allow(
            clippy::cast_possible_truncation,
            reason = "a seed only needs to differ"
        )]
        seed: (id as u32).wrapping_mul(2_654_435_761),
        version: 1,
        outline: Vec::new(),
        previous: Vec::new(),
        bounds: None,
        extent: [0.0; 4],
        erasing: false,
    }
}

crates/core/src/ink.rs::Element.preview.source_code:
pub(crate) fn preview(&mut self, scratch: &mut Scratch) -> Option<Rect> {
