}

crates/core/src/ink.rs::Element.push.source_code:
pub(crate) fn push(
    &mut self,
    at: Point,
    pressure: Option<f32>,
    scratch: &mut Scratch,
) -> Option<Rect> {
    let local = Point {
        x: at.x - self.x,
        y: at.y - self.y,
    };
    if self.points.last() == Some(&local) {
        return None;
    }
    self.append(local, pressure);
    self.refresh(scratch, false)
}

crates/core/src/ink.rs::Element.commit.source_code:
pub(crate) fn commit(
    &mut self,
    at: Point,
    pressure: Option<f32>,
    scratch: &mut Scratch,
) -> Option<Rect> {
    let mut local = Point {
        x: at.x - self.x,
        y: at.y - self.y,
    };
    if self.points.first() == Some(&local) {
        local.x += 0.0001;
        local.y += 0.0001;
    }
    self.append(local, pressure);
    self.close_loop();
    self.refresh(scratch, true)
}

crates/core/src/ink.rs::Element.commit.docstring:
/// Ends the Stroke at `at`: the point is always kept (a dot gets
/// Excalidraw's 0.0001 nudge, a near-closed path is closed) and the cached
/// outline is recomputed with `last`.

crates/core/src/ink.rs::Element.finish.source_code:
