crates/core/src/ink.rs::Element.set_styl.source_code:
pub(crate) fn set_style(&mut self, style: Appearance, scratch: &mut Scratch) -> Option<Rect> {
    let old = self.bounds;
    #[allow(clippy::float_cmp, reason = "widths are picked from a fixed list")]
    let resized = style.width != self.stroke_width;
    (self.stroke_color, self.stroke_width) = (style.color, style.width);
    self.version = self.version.wrapping_add(1);
    if resized {
        self.refresh(scratch, true);
    }
    match (old, self.bounds) {
        (Some(old), Some(new)) => Some([
            old[0].min(new[0]),
            old[1].min(new[1]),
            old[2].max(new[2]),
            old[3].max(new[3]),
        ]),
        (either, other) => either.or(other),
    }
}

