pub(crate) fn is_near(&self, at: Point, threshold: f32) -> bool {
    let (x, y) = (at.x - self.x, at.y - self.y);
    let limit = threshold * threshold;
    match self.points.as_slice() {
        [only] => distance_squared((x, y), *only, *only) <= limit,
        points => points
            .windows(2)
            .any(|w| distance_squared((x, y), w[0], w[1]) <= limit),
    }
}

crates/core/src/ink.rs::Element.is_near.docstring:
/// Whether `at` (logical, absolute) is within `threshold` of the input
/// polyline. Like Excalidraw's hit test (`getFreedrawShape`), this is the
/// centreline of the points, not the filled outline.

crates/core/src/ink.rs::distance_squared.source_code:
fn distance_squared((x, y): (f32, f32), a: Point, b: Point) -> f32 {
    let (dx, dy) = (b.x - a.x, b.y - a.y);
    let length = dx * dx + dy * dy;
    let t = if length > 0.0 {
        (((x - a.x) * dx + (y - a.y) * dy) / length).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let (px, py) = (a.x + t * dx - x, a.y + t * dy - y);
    px * px + py * py
}

crates/core/src/ink.rs::union_of.source_code:
fn union_of(vertices: impl Iterator<Item = [f32; 2]>) -> Option<Rect> {
    vertices.fold(None, |acc, [x, y]| {
        Some(match acc {
            None => [x, y, x, y],
            Some([l, t, r, b]) => [l.min(x), t.min(y), r.max(x), b.max(y)],
        })
    })
}

crates/core/src/ink.rs::span.source_code:
fn span(v: &[[f32; 2]], head: usize, tail: usize) -> impl Iterator<Item = [f32; 2]> + '_ {
    let from = head.saturating_sub(2);
    let to = (v.len() + 2).saturating_sub(tail).min(v.len());
    v.get(from..to).unwrap_or(&[]).iter().copied()
}

crates/core/src/ink.rs::changed_box.source_code:
fn changed_box(old: &[[f32; 2]], new: &[[f32; 2]]) -> Option<Rect> {
    let shortest = old.len().min(new.len());
    let head = old.iter().zip(new).take_while(|(a, b)| a == b).count();
    let tail = old
        .iter()
        .rev()
        .zip(new.iter().rev())
        .take(shortest - head)
        .take_while(|(a, b)| a == b)
        .count();
    if head == old.len() && head == new.len() {
        return None;
    }
    union_of(span(old, head, tail).chain(span(new, head, tail)))
}

crates/core/src/ink.rs::changed_box.docstring:
/// Box covering everything that differs between two outlines. Outlines are
/// deterministic, so the vertices only change in one run: the common head and
