pub(crate) fn mark_near(
    &mut self,
    at: Point,
    threshold: f32,
    mut changed: impl FnMut(&Element),
) {
    for e in self.elements.iter_mut().filter(|e| !e.erasing) {
        if e.is_near(at, threshold) {
            e.erasing = true;
            changed(e);
        }
    }
