pub fn get_trail(points: &[[f64; 3]], now: f64, closed: bool) -> Vec<[f64; 2]> {
    let mut pointer = Pointer::default();
    for &p in points {
        pointer.add_point(p);
    }
    if closed {
        pointer.stabilize_tail();
    }
    let mut out = Vec::new();
    pointer.outline(now, &mut Scratch::default(), &mut out);
    out
}

