fn shape(&mut self, build: impl FnOnce(&mut PathBuilder)) -> Option<Path> {
    let mut path = self.builder.take().unwrap_or_default();
    build(&mut path);
    if path.len() < 2 {
        path.clear();
        *self.builder = Some(path);
        return None;
    }
    path.finish()
}

