pub fn fill_with(&mut self, build: impl FnOnce(&mut PathBuilder), paint: &Paint<'_>) {
    if let Some(path) = self.shape(build) {
        self.pm
            .fill_path(&path, paint, FillRule::Winding, self.shift, None);
        *self.builder = Some(path.clear());
    }
}

