pub fn draw_pixmap(
    &mut self,
    build: impl FnOnce(&mut PathBuilder),
    pixels: PixmapRef<'_>,
    origin: (f32, f32),
) {
    let paint = Paint {
        shader: Pattern::new(
            pixels,
            SpreadMode::Pad,
            FilterQuality::Nearest,
            1.0,
            Transform::from_translate(origin.0, origin.1),
        ),
        anti_alias: true,
        ..Paint::default()
    };
    self.fill_with(build, &paint);
}

