pub fn look(
    &self,
    frame: &Frame,
    theme: Theme,
    value: SlotValue,
    stroke: [u8; 3],
    recent: RecentColors,
) -> Option<Look> {
    let open = self.open?;
    let geom = self.geometry(frame)?;
    let custom = open.kind == SlotKind::Color && self.tab == Tab::Custom;
    Some(Look {
        geom,
        hover: open.hover,
        hsv: if custom { open.hsv } else { NO_HSV },
        value,
        stroke: if open.kind == SlotKind::Width {
            stroke
        } else {
            [0; 3]
        },
        recent,
        theme,
    })
}

