crates/core/src/picker/paint.rs::Picker..source_code:
pub fn paint(&mut self, target: &mut Painter<'_, '_>, look: &Look, format: Format) {
    let g = look.geom;
    let rect = g.rect();
    let s = g.rect_scale();
    let tokens = look.theme.tokens();
    shadow(target, rect, s, format);
    fill_rounded(
        target,
        rect,
        RADIUS * s,
        &solid_paint(tokens.island, 1.0, format),
    );
    let Some(glyphs) = self.glyphs.as_ref() else {
        return;
    };
    let mut brush = Brush {
        glyphs,
        target,
        tokens,
        format,
        s,
    };
    match (g.kind, g.tab) {
        (SlotKind::Width, _) => brush.width(look),
        (SlotKind::Color, tab) => {
            brush.tabs(look);
            match tab {
                Tab::Presets => brush.presets(look),
                Tab::Custom => brush.custom(&mut self.custom, look),
            }
            brush.footer(look);
        }
    }
}

crates/core/src/picker/paint.rs::circle.source_code:
fn circle(pb: &mut PathBuilder, cx: f32, cy: f32, r: f32) {
    const K: f32 = 0.552_284_8;
    let k = r * K;
    pb.move_to(cx + r, cy);
    pb.cubic_to(cx + r, cy + k, cx + k, cy + r, cx, cy + r);
    pb.cubic_to(cx - k, cy + r, cx - r, cy + k, cx - r, cy);
    pb.cubic_to(cx - r, cy - k, cx - k, cy - r, cx, cy - r);
    pb.cubic_to(cx + k, cy - r, cx + r, cy - k, cx + r, cy);
    pb.close();
}

