pub struct Pending {
    full: bool,
    /// Union of changed rectangles, physical `[l, t, r, b]`.
    dirty: Option<Rect>,
    /// The Scroll, logical px. It lives here because every layer that maps Ink
    /// to pixels already receives the `Pending`.
    scroll: f32,
    scratch: Vec<u8>,
    builder: Option<PathBuilder>,
}

crates/core/src/render.rs::Pending.full.source_code:
pub fn full(&mut self) {
    self.full = true;
}

crates/core/src/render.rs::Pending.scrol.source_code:
pub fn scroll_by(&mut self, dy: f32) {
    // Clamped so f32 keeps sub-pixel precision for the coordinates that
    // result (at 1e6 the spacing between floats is still 0.06 px).
    let scroll = (self.scroll + dy).clamp(-MAX_SCROLL, MAX_SCROLL);
    // Rule 7: a zero step (a trackpad's momentum tail) redraws nothing.
    self.full |= scroll.to_bits() != self.scroll.to_bits();
    self.scroll = scroll;
}

crates/core/src/render.rs::Pending.is_pe.source_code:
pub fn is_pending(&self) -> bool {
    self.full || self.dirty.is_some()
}

crates/core/src/render.rs::Pending.touch.source_code:
pub fn touches(&self, rect: Rect) -> bool {
    self.full
        || self.dirty.is_some_and(|[l, t, r, b]| {
            l < rect[2] && rect[0] < r && t < rect[3] && rect[1] < b
        })
}

crates/core/src/render.rs::Pending.take_.source_code:
fn take_damage(&mut self, width: u32, height: u32) -> Option<Damage> {
    if self.full {
        self.full = false;
        self.dirty = None;
        return Some(Damage {
            x: 0,
            y: 0,
            width,
            height,
        });
    }
    damage_of(self.dirty.take()?, width, height)
}

crates/core/src/render.rs::Pending.add_p.source_code:
pub fn add_physical(&mut self, rect: Rect) {
    self.dirty = Some(match self.dirty {
        None => rect,
        Some([ol, ot, or, ob]) => [
            rect[0].min(ol),
            rect[1].min(ot),
            rect[2].max(or),
            rect[3].max(ob),
        ],
    });
}

crates/core/src/render.rs::Pending.damag.source_code:
pub fn damage_local(&mut self, local: Rect, origin: (f32, f32), scale: f32) {
    let [left, top, right, bottom] = local;
    let (ox, oy) = (origin.0, origin.1 + self.scroll);
    let rect = [
        (left + ox) * scale - DAMAGE_PAD,
        (top + oy) * scale - DAMAGE_PAD,
        (right + ox) * scale + DAMAGE_PAD,
        (bottom + oy) * scale + DAMAGE_PAD,
    ];
    if !rect.iter().all(|v| v.is_finite()) {
        return;
    }
    self.dirty = Some(match self.dirty {
        None => rect,
        Some([ol, ot, or, ob]) => [
            rect[0].min(ol),
            rect[1].min(ot),
            rect[2].max(or),
            rect[3].max(ob),
        ],
    });
}

