fn overlaps(a: Rect, b: Rect) -> bool {
    a[0] < b[2] && b[0] < a[2] && a[1] < b[3] && b[1] < a[3]
}

crates/core/src/render.rs::compose_band.source_code:
fn compose_band(
    layers: &Layers<'_>,
    pending: &mut Pending,
    (chrome, popover): (&mut Chrome<'_>, &mut Popover<'_>),
    target: &mut PixmapMut<'_>,
    band: Damage,
) {
    let Layers {
        scroll,
        ink,
        laser,
        selection,
        draw_mode,
        scale,
        format,
    } = *layers;
    let row_bytes = band.width as usize * 4;
    let len = row_bytes * band.height as usize;
    let Pending {
        scratch, builder, ..
    } = pending;
    if scratch.len() < len {
        scratch.resize(len, 0);
    }
    let Some(bytes) = scratch.get_mut(..len) else {
        return;
    };
    let Some(mut region) = PixmapMut::from_bytes(bytes, band.width, band.height) else {
        return;
    };
    // In Draw Mode the Overlay needs alpha 1 everywhere, otherwise the OS
    // sends clicks on fully transparent pixels to the apps underneath.
    region.fill(Color::from_rgba8(0, 0, 0, u8::from(draw_mode)));
    draw_elements(
        ink,
        laser,
        builder,
        &mut region,
        band,
        (scale, scroll),
        format,
    );
    let mut painter = Painter::new(&mut region, (band.x, band.y), builder);
    let this = Area::from_bounds(bounds_of(band));
    if selection
        .shown()
        .is_some_and(|area| overlaps(area, bounds_of(band)))
    {
        selection.paint(ink, &mut painter, scale, format, scroll);
    }
    if chrome.region().is_some_and(|r| r.intersects(&this)) {
        chrome.paint(&mut painter, format);
    }
    if let Some(look) = popover.look.filter(|l| l.region().intersects(&this)) {
        popover.picker.paint(&mut painter, &look, format);
    }
    let stride = target.width() as usize * 4;
    let data = target.data_mut();
    let Some(rendered) = scratch.get(..len) else {
        return;
    };
    for (row, src) in rendered.chunks_exact(row_bytes).enumerate() {
        let start = (band.y as usize + row) * stride + band.x as usize * 4;
        if let Some(dst) = data.get_mut(start..start + row_bytes) {
            dst.copy_from_slice(src);
        }
    }
}

crates/core/src/render.rs::compose_band.docstring:
/// Composes every layer of one band of the damaged region in the scratch
/// pixmap, then copies the finished band into the target in one pass.
///
/// The target is what the screen shows (on macOS the displayed `IOSurface`), and
/// the compositor reads it at any moment. Painting layer after layer into it
/// let a sample catch the band cleared and the toolbar not yet
/// painted: a flicker while hovering them (ADR-0003). Here each target pixel
/// is written once, with its final value, so no partial layer state is ever
/// visible.

crates/core/src/render.rs::draw_elements.source_code:
fn draw_elements(
    ink: &Ink,
    laser: &Laser,
    builder: &mut Option<PathBuilder>,
    pm: &mut PixmapMut<'_>,
    view: Damage,
    (scale, scroll): (f32, f32),
    format: Format,
) {
    let (ox, oy) = (to_f32(view.x), to_f32(view.y));
    let (vr, vb) = (ox + to_f32(view.width), oy + to_f32(view.height));
    for element in ink.elements() {
        let Some([l, t, r, b]) = element.bounds() else {
            continue;
        };
        let (ex, ey) = (element.x(), element.y() + scroll);
        let touches = (l + ex) * scale - DAMAGE_PAD < vr
            && (r + ex) * scale + DAMAGE_PAD > ox
            && (t + ey) * scale - DAMAGE_PAD < vb
            && (b + ey) * scale + DAMAGE_PAD > oy;
        if touches {
            fill_element(element, builder, pm, (scale, scroll, ox, oy), format);
        }
    }
    laser.fill(builder, pm, (scale, ox, oy), format == Format::Bgra);
}

crates/core/src/render.rs::fill_element.source_code:
fn fill_element(
    element: &Element,
    builder: &mut Option<PathBuilder>,
    pm: &mut PixmapMut<'_>,
    (scale, scroll, ox, oy): (f32, f32, f32, f32),
    format: Format,
) {
    let outline = element.outline();
    if outline.len() < 3 {
        return;
    }
    let (ex, ey) = (element.x(), element.y() + scroll);
    let absolute = |v: [f32; 2]| ((v[0] + ex) * scale, (v[1] + ey) * scale);
    let mut path = builder.take().unwrap_or_default();
    // `outline.len() >= 3` was checked above, so both indexings are in range
    // and the modulo cannot divide by zero.
    let (x0, y0) = absolute(outline[0]);
    path.move_to(x0 - ox, y0 - oy);
    for (i, &v) in outline.iter().enumerate() {
        let (x, y) = absolute(v);
        let (nx, ny) = absolute(outline[(i + 1) % outline.len()]);
        path.quad_to(
            x - ox,
            y - oy,
            f32::midpoint(x, nx) - ox,
            f32::midpoint(y, ny) - oy,
        );
    }
    path.line_to(x0 - ox, y0 - oy);
    path.close();
    if let Some(path) = path.finish() {
        pm.fill_path(
            &path,
            &ink_paint(element, format),
            FillRule::Winding,
            Transform::identity(),
            None,
        );
        *builder = Some(path.clear());
    }
}

crates/core/src/render.rs::fill_element.docstring:
/// Fills one Element. Vertices are mapped to absolute target pixels first and
/// the integer view origin is subtracted last: that subtraction is exact, so a
/// band redraw rasterizes bit-identically to a full redraw (a combined
/// transform would round differently and flip edge-coverage samples).

crates/core/src/render.rs::ink_paint.source_code:
fn ink_paint(element: &Element, format: Format) -> Paint<'static> {
    let [r, g, b] = element.stroke_color();
    let (r, b) = if format == Format::Bgra {
        (b, r)
    } else {
        (r, b)
    };
    // Excalidraw draws Elements pending erasure at a fifth of their opacity.
    let fifth = if element.is_erasing() { 5 } else { 1 };
    let alpha = u16::from(element.opacity().min(100)) * 255 / 100 / fifth;
    let mut paint = Paint::default();
    paint.set_color_rgba8(r, g, b, u8::try_from(alpha).unwrap_or(255));
    paint.anti_alias = true;
    paint
}

crates/core/src/render.rs::bounds_of.source_code:
fn bounds_of(d: Damage) -> Rect {
    [
        to_f32(d.x),
        to_f32(d.y),
        to_f32(d.x + d.width),
        to_f32(d.y + d.height),
    ]
}

crates/core/src/render.rs::damage_of.source_code:
fn damage_of([left, top, right, bottom]: Rect, width: u32, height: u32) -> Option<Damage> {
    let clamp = |v: f32, max: u32| v.clamp(0.0, to_f32(max)) as u32;
    let (x0, y0) = (clamp(left.floor(), width), clamp(top.floor(), height));
    let (x1, y1) = (clamp(right.ceil(), width), clamp(bottom.ceil(), height));
    (x1 > x0 && y1 > y0).then(|| Damage {
        x: x0,
        y: y0,
        width: x1 - x0,
        height: y1 - y0,
    })
}

crates/core/src/render.rs::to_f32.source_code:
fn to_f32(v: u32) -> f32 {
    v as f32
}

crates/core/src/route/mod.rs::Annotator..source_code:
pub fn handle(&mut self, event: Event) -> View {
    self.edit = None;
    // A press that has no picker to belong to starts afresh: the release
    // of the one that opened the system panel may never arrive.
    if matches!(event, Event::PointerDown(_)) && !self.picker.is_open() {
        self.dismissing = false;
    }
    match event {
        Event::ToggleDrawMode(display) => self.toggle(display),
        Event::SurfaceReset => self.paint.full(),
        Event::Resize { width, height } => {
            self.toolbar.resize(width, height);
            self.paint.full();
        }
        Event::Insets(insets) => {
            self.toolbar.set_insets(insets);
            self.paint.full();
        }
        Event::ToolbarPosition(position) => {
            self.toolbar.set_position(position);
            self.paint.full();
        }
        Event::Style(style) if style.is_valid() => {
            self.slots = style;
            self.resolve_style();
        }
        Event::Palette(palette) => {
            self.palette = palette.sanitized();
            self.resolve_style();
        }
        Event::EditColor { slot, rgb } if slot < COLORS => {
            self.palette.colors[slot] = rgb;
            self.panel_run = Some(slot);
            self.edit_slot(SlotKind::Color, slot, Choice::Color(slot));
        }
        Event::EditEnd => {
            self.finish_restyle();
            if let Some(slot) = self.panel_run.take() {
                if let Some(SlotValue::Color(rgb)) = self.palette.get(SlotKind::Color, slot) {
                    self.recent.push(rgb);
                }
            }
        }
        Event::RecentColors(recent) => self.recent = recent,
        Event::SecondaryClick(at) if self.draw_mode => self.secondary_click(at),
        Event::Theme(theme) => {
            self.toolbar.theme = theme;
            self.selection.set_theme(theme);
        }
        Event::Modifiers { shift, alt } => {
            self.shift = shift;
            self.alt = alt;
        }
        Event::Pressure(p) => self.pressure = p.filter(|p| p.is_finite()),
        Event::Scroll { dy }
            if self.draw_mode
                && dy.is_finite()
                && !self.tool_busy()
                && !self.picker.dragging()
                && !self.toolbar.pressing() =>
        {
            let (_, mut ctx) = self.tool();
            ctx.scroll_by(dy / ctx.scale);
        }
        Event::ScaleFactor(scale) if scale.is_finite() && scale > 0.0 => {
            self.scale = scale;
            self.toolbar.set_scale(scale);
            self.paint.full();
        }
        Event::PointerDown(at) if self.draw_mode && self.picker.is_open() => {
            self.picker_down(at);
        }
        Event::PointerMove(at) if self.draw_mode && self.picker.dragging() => {
            self.picker_drag(at);
        }
        Event::PointerUp(_) if self.draw_mode && self.picker.dragging() => {
            self.picker_release();
        }
        Event::PointerUp(_) if self.dismissing => self.dismissing = false,
        Event::PointerMove(_) if self.dismissing => {}
        Event::PointerMove(at) if self.draw_mode && self.picker.is_open() => {
            self.picker_hover(at);
        }
        Event::PointerDown(at) if self.draw_mode => self.pointer_down(at),
        Event::PointerMove(at) if self.draw_mode => self.pointer_move(at),
        Event::PointerUp(at) if self.draw_mode => self.pointer_up(at),
        Event::Key {
            key,
            command,
            shift,
            alt,
        } if self.draw_mode => self.key(key, command, shift, alt),
        Event::Clear => self.clear(),
        Event::Clock(ms) => self.laser.set_now(ms, &mut self.paint, self.scale),
        _ => {}
    }
    self.selection.flush(&self.ink, &mut self.paint, self.scale);
    self.view()
}

fn choose(&mut self, choice: Choice) {
    let target = self.tools.get(self.tools.active()).map(Tool::styles);
    let palette = self.palette;
    match target {
        Some(StyleTarget::Selection) if !self.selection.is_empty() => style::restyle(
            &mut self.ink,
            self.selection.ids(),
            |appearance| appearance.with(choice, &palette),
            &mut self.restyling,
            (&mut self.freehand, &mut self.paint, self.scale),
        ),
        Some(StyleTarget::NextStrokes) => self.choose_for_pen(choice),
        _ => {
            self.switch_tool(|tools| tools.select_by_kind(ToolKind::Pen));
            self.choose_for_pen(choice);
        }
    }
}

crates/core/src/route/mod.rs::Annotator..docstring:
/// A style choice, from a key, a Toolbar click or a Palette edit. The
/// active Tool's [`StyleTarget`] decides, never its kind: a Selection is
/// restyled, the next Strokes take the Style, and a Tool with neither
/// hands over to the Pen first.

crates/core/src/route/mod.rs::Annotator..source_code:
fn choose_for_pen(&mut self, choice: Choice) {
    self.slots = choice.pinned(self.slots).slots(self.slots);
    self.resolve_style();
}

fn resolve_style(&mut self) {
    self.style = Appearance::of(self.slots, &self.palette);
}

fn choose_by_key(&mut self, choice: Choice) {
    self.choose(choice);
    self.finish_restyle();
}

fn edit_slot(&mut self, kind: SlotKind, index: usize, choice: Choice) {
    if self.editing != Some((kind, index)) {
        self.finish_restyle();
    }
    self.resolve_style();
    self.choose(choice);
    self.editing = Some((kind, index));
}

fn finish_restyle(&mut self) {
    self.editing = None;
    style::finish(self.restyling.take(), &self.ink, &mut self.history);
}

fn tool(&mut self) -> (&mut dyn Tool, Ctx<'_>) {
    let ctx = Ctx {
        ink: &mut self.ink,
        history: &mut self.history,
        paint: &mut self.paint,
        freehand: &mut self.freehand,
        selection: &mut self.selection,
        laser: &mut self.laser,
        next_id: &mut self.next_id,
        scale: self.scale,
        pressure: self.pressure,
        shift: self.shift,
        style: self.style,
    };
    (self.tools.active_mut(), ctx)
}

pub(super) fn tool_busy(&self) -> bool {
    self.tools.in_use().is_some_and(Tool::busy)
}

fn finish_gesture(&mut self) {
    let (tool, mut ctx) = self.tool();
    tool.finish(&mut ctx);
    self.tools.temp_hand = false;
    self.finish_restyle();
}

fn pointer_down(&mut self, at: Point) {
    self.finish_gesture();
    if self.toolbar.press_at(at, self.tools.len()) {
        return;
    }
    self.tools.temp_hand = self.alt;
    let (tool, mut ctx) = self.tool();
    tool.pointer_down(&mut ctx, at);
}

fn pointer_move(&mut self, at: Point) {
    self.toolbar.hover_at(at, self.tools.len());
    if !self.toolbar.pressing() {
        let (tool, mut ctx) = self.tool();
        tool.pointer_move(&mut ctx, at);
    }
}

fn pointer_up(&mut self, at: Point) {
    if self.toolbar.pressing() {
        if let Some(button) = self.toolbar.release_at(at, self.tools.len()) {
            // Read before the click chooses the slot: a click on the slot
            // that was already chosen opens its picker.
            let was = self.chosen_style();
            self.activate(button);
            self.open_if_chosen(button, &was);
        }
    } else {
        self.toolbar.hover_at(at, self.tools.len());
        let (tool, mut ctx) = self.tool();
        tool.pointer_up(&mut ctx, at);
        self.tools.temp_hand = false;
    }
}

fn activate(&mut self, button: Button) {
    match button {
        Button::Tool(index) => self.switch_tool(|tools| tools.select(index)),
        Button::Color(i) => self.choose_by_key(Choice::Color(i)),
        Button::Width(i) => self.choose_by_key(Choice::Width(i)),
        Button::Undo => self.undo(),
        Button::Redo => self.redo(),
        Button::Clear => self.clear(),
    }
}

fn key(&mut self, key: Key, command: bool, shift: bool, alt: bool) {
    if key == Key::Escape && self.picker.is_open() {
        self.picker_escape();
        return;
    }
    // A key now would split the drag's undo step or change what it edits.
    if self.picker.dragging() {
        return;
    }
    self.finish_restyle();
    let (tool, mut ctx) = self.tool();
    if tool.key(&mut ctx, key, command, shift) {
        return;
    }
    match (key, command, shift) {
        // Undo, redo and switching wait for the Stroke to end: it is not
        // logged yet.
        (Key::Char(_), _, _) if self.tool_busy() => {}
        // A style choice would change the Style under the press.
        (Key::Char('1'..='5' | '[' | ']'), false, _) if self.toolbar.pressing() => {}
        (Key::Char('z'), true, false) => self.undo(),
        (Key::Char('z'), true, true) | (Key::Char('y'), true, false) => self.redo(),
        (Key::Char('a'), true, false) => {
            // Like Excalidraw, Select All leaves the Pen for the Select Tool.
            self.switch_tool(|tools| {
                tools.select_by_key('v');
            });
            self.selection.select_all(&self.ink);
        }
        (Key::Char('c'), true, false) => self.copy(),
        // Shift+digit stays ignored: on AZERTY the digits are shifted.
        (Key::Char(c @ '1'..='5'), false, false) if !alt => {
            let index = c
                .to_digit(10)
                .and_then(|d| usize::try_from(d.checked_sub(1)?).ok())
                .unwrap_or(0);
            self.choose_by_key(Choice::Color(index));
        }
        (Key::Char('['), false, _) => self.choose_by_key(Choice::Thinner),
        (Key::Char(']'), false, _) => self.choose_by_key(Choice::Bolder),
        (Key::Char(' '), false, false) if !alt => self.clear(),
        // A page is most of a screen, so a strip of the Ink stays in view.
        (Key::PageUp | Key::PageDown, false, false)
            if !self.tool_busy() && !self.toolbar.pressing() =>
        {
            let page = 0.9 * self.toolbar.overlay_height() / self.scale;
            let (_, mut ctx) = self.tool();
            ctx.scroll_by(if key == Key::PageUp { page } else { -page });
        }
        // Esc with nothing left to cancel leaves Draw Mode, like the hotkey.
        (Key::Escape, false, false) if !alt => {
            if let Some(display) = self.display {
                self.toggle(display);
            }
        }
        (Key::Char(c), false, false) if !alt => {
            self.switch_tool(|tools| tools.press(c));
        }
        _ => {}
    }
}

fn switch_tool(&mut self, change: impl FnOnce(&mut Tools)) {
    let before = self.tools.active();
    change(&mut self.tools);
    if self.tools.active() != before {
        self.selection.clear();
    }
}

fn copy(&mut self) {
    let chosen = |e: &&Element| self.selection.is_empty() || self.selection.contains(e.id());
    self.copied = excalidraw::clipboard(self.ink.elements().iter().filter(chosen));
}

fn undo(&mut self) {
    if self.history.undo(&mut self.ink, &mut self.freehand) {
        self.ink_replaced();
    }
}

fn redo(&mut self) {
    if self.history.redo(&mut self.ink, &mut self.freehand) {
        self.ink_replaced();
    }
}

fn ink_replaced(&mut self) {
    self.selection.retain_existing(&self.ink);
    self.selection.touch();
    self.paint.full();
}

fn clear(&mut self) {
    self.finish_gesture();
    if !self.ink.is_empty() {
        self.history.record_clear(self.ink.take());
    }
    // Draw Mode is untouched: Clear empties the Ink, nothing more.
    self.selection.clear();
    self.laser.clear();
    self.paint.reset_scroll();
    self.paint.full();
}

fn toggle(&mut self, display: DisplayId) {
    self.finish_gesture();
    self.picker.free();
    self.dismissing = false;
    self.toolbar.forget_pointer();
    self.selection.clear();
    if self.draw_mode {
        self.draw_mode = false;
        self.laser.clear();
    } else {
        if self.display != Some(display) {
            // ADR-0002: the history belongs to the Ink that was Cleared.
            self.ink = Ink::default();
            self.paint.reset_scroll();
            self.history.reset();
        }
        self.display = Some(display);
        self.draw_mode = true;
        self.tools.reset();
    }
    // Backdrop (hit-test layer) appears and disappears with Draw Mode.
    self.paint.full();
}

crates/core/src/route/picker.rs::Annotat.source_code:
pub(crate) fn picker_frame(&self) -> Option<Frame> {
    let (kind, index) = self.picker.slot()?;
    let (anchor, side, usable) = self.toolbar.slot_geometry(kind, index, self.tools.len())?;
    Some(Frame {
        anchor,
        side,
        usable,
        scale: self.scale,
    })
}

pub(crate) fn picker_look(&self) -> Option<Look> {
    let (kind, index) = self.picker.slot()?;
    let frame = self.picker_frame()?;
    let value = self.slot_value(kind, index)?;
    self.picker.look(
        &frame,
        self.toolbar.theme,
        value,
        self.style.color,
        self.recent,
    )
}

fn slot_value(&self, kind: SlotKind, index: usize) -> Option<SlotValue> {
    self.palette.get(kind, index)
}

fn open_picker(&mut self, kind: SlotKind, index: usize) {
    let Some(value) = self.slot_value(kind, index) else {
        return;
    };
    self.finish_restyle();
    self.picker.open(kind, index, value);
}

pub(super) fn open_if_chosen(&mut self, button: Button, was: &Chosen) {
    if was.dimmed {
        return;
    }
    match button {
        Button::Color(i) if was.color == Some(i) => self.open_picker(SlotKind::Color, i),
        Button::Width(i) if was.width == Some(i) => self.open_picker(SlotKind::Width, i),
        _ => {}
    }
}

pub(super) fn secondary_click(&mut self, at: Point) {
    if self.tool_busy() || self.toolbar.pressing() || self.picker.dragging() {
        return;
    }
    if let Some(frame) = self.picker_frame() {
        if self.picker.contains(at, &frame) {
            return;
        }
    }
    match self.toolbar.slot_at(at, self.tools.len()) {
        Some((kind, index)) => self.open_picker(kind, index),
        None => self.picker.close(),
    }
}

pub(super) fn picker_down(&mut self, at: Point) {
    let (Some(frame), Some((kind, index))) = (self.picker_frame(), self.picker.slot()) else {
        self.picker.close();
        return;
    };
    self.dismissing = true;
    let Some(value) = self.slot_value(kind, index) else {
        return;
    };
    if !self.picker.contains(at, &frame) {
        self.finish_restyle();
        self.picker.close();
        return;
    }
    match self.picker.press(at, &frame, value, &self.recent) {
        Outcome::Pick(rgb) => {
            self.set_slot(kind, index, SlotValue::Color(rgb));
            self.finish_restyle();
            self.recent.push(rgb);
            self.picker.close();
        }
        Outcome::Set(value) => {
            // A drag has started: its moves and release are the picker's.
            self.dismissing = false;
            self.set_slot(kind, index, value);
        }
        Outcome::Reset => {
            if let Some(default) = Palette::default_slot(kind, index) {
                self.set_slot(kind, index, default);
            }
            self.finish_restyle();
            self.picker.close();
        }
        Outcome::More => {
            self.picker.close();
            self.edit = self.system_panel_request(index, &frame);
        }
        Outcome::Tab | Outcome::Inert => {}
    }
}

fn system_panel_request(&self, index: usize, frame: &Frame) -> Option<EditRequest> {
    let value = self.slot_value(SlotKind::Color, index)?;
    let a = frame.anchor;
    Some(EditRequest {
        kind: SlotKind::Color,
        index,
        anchor: Anchor {
            x: a.x,
            y: a.y,
            w: a.w,
            h: a.h,
        },
        side: frame.side,
        value,
    })
}

fn set_slot(&mut self, kind: SlotKind, index: usize, value: SlotValue) {
    if !self.palette.set(kind, index, value) {
        return;
    }
    if kind == SlotKind::Color && self.panel_run == Some(index) {
        self.panel_run = None;
    }
    let choice = match kind {
        SlotKind::Color => Choice::Color(index),
        SlotKind::Width => Choice::Width(index),
    };
    self.edit_slot(kind, index, choice);
}

