fn dashed_stroke(scale: f32) -> Stroke {
    Stroke {
        width: scale.round().max(1.0),
        dash: StrokeDash::new(vec![2.0 * scale, 2.0 * scale], 0.0),
        ..Stroke::default()
    }
}

crates/core/src/selection.rs::outline.source_code:
fn outline(
    target: &mut Painter<'_, '_>,
    rect: Rect,
    scale: f32,
    paint: &Paint<'_>,
    stroke: &Stroke,
) {
    let [l, t, r, b] = snap(rect, scale);
    let half = stroke.width / 2.0;
    if let Some(path) =
        SkiaRect::from_ltrb(l + half, t + half, r + half, b + half).map(PathBuilder::from_rect)
    {
        target.stroke_path(&path, paint, stroke, Transform::identity());
    }
}

crates/core/src/selection.rs::snap.source_code:
fn snap([l, t, r, b]: Rect, scale: f32) -> Rect {
    [
        (l * scale).round(),
        (t * scale).round(),
        (r * scale).round(),
        (b * scale).round(),
    ]
}

crates/core/src/selection.rs::stroke_pai.source_code:
fn stroke_paint(rgb: [u8; 3], alpha: f32, format: Format) -> Paint<'static> {
    let [r, g, b] = rgb;
    let (r, b) = if format == Format::Bgra {
        (b, r)
    } else {
        (r, b)
    };
    let mut paint = Paint::default();
    paint.set_color(Color::from_rgba8(r, g, b, alpha_byte(alpha)));
    paint.anti_alias = true;
    paint
}

crates/core/src/selection.rs::alpha_byte.source_code:
fn alpha_byte(alpha: f32) -> u8 {
    (alpha.clamp(0.0, 1.0) * 255.0).round() as u8
}

crates/core/src/selection.rs::grow.source_code:
fn grow([l, t, r, b]: Rect, by: f32) -> Rect {
    [l - by, t - by, r + by, b + by]
}

crates/core/src/selection.rs::lower.source_code:
