pub fn press(&mut self, key: char) {
    let partner = self
        .list
        .get(self.active)
        .and_then(|t| t.toggle())
        .filter(|(keys, _)| keys.contains(&key))
        .and_then(|(_, kind)| self.list.iter().position(|t| t.kind() == kind));
    match partner {
        Some(index) => self.active = index,
        None => {
            self.select_by_key(key);
        }
    }
}

