    if let Some(index) = self.list.iter().position(|t| t.kind() == kind) {
        self.active = index;
    }
}

pub fn select_by_key(&mut self, key: char) -> bool {
    match self.list.iter().position(|t| t.keys().contains(&key)) {
        Some(index) => {
            self.active = index;
            true
        }
        None => false,
    }
}

