            || self.picker.is_dirty(self.picker_look()),
        cursor: match self.tools.in_use() {
            Some(_) if alt_hand && !over_toolbar => Cursor::Hand { grabbing: false },
            Some(tool) if !over_toolbar => tool.cursor(self.style),
            _ => Cursor::Arrow,
