fn redraw(&mut self) {
    let Some(overlay) = self.overlay.as_mut() else {
        return;
    };
    let mut buffer = overlay.presenter.buffer();
    if let Some(damage) = self.core.render(&mut buffer, platform::FORMAT) {
        overlay.presenter.present(damage);
    }
}

