fn add_toolbar_row(
    content: &NSView,
    target: &AnyObject,
    current: ToolbarPosition,
    mtm: MainThreadMarker,
) {
    let label = NSTextField::labelWithString(&NSString::from_str("Toolbar"), mtm);
    label.setFrame(NSRect::new(
        NSPoint::new(20.0, 114.0),
        NSSize::new(160.0, 20.0),
    ));
